mapper.select:
SELECT s.*, g.group_name FROM scene_info s LEFT JOIN scene_group g ON s.group_id = g.id WHERE s.deleted = 0
AND s.scene_name LIKE CONCAT('%', #{sceneName}, '%')
AND s.group_id = #{groupId}
AND s.status = #{status}
ORDER BY s.created_at DESC

mapper.update:
UPDATE scene_info
scene_name = #{sceneName}, group_id = #{groupId}, description = #{description}, status = #{status}, updated_at = NOW()
WHERE id = #{id}
